// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount < type(uint256).max / 2);

        uint256 initialMint = amount * 2;
        address owner = c.owner();
        vm.prank(owner);
        c.mintToken(owner, initialMint);

        uint256 preTotal = c.totalSupply();
        uint256 preBal = c.balanceOf(owner);

        vm.prank(owner);
        c.burn(amount);

        uint256 postTotal = c.totalSupply();
        uint256 postBal = c.balanceOf(owner);
        assertTrue(postBal == postTotal);
    }
}
